-- Catalog-only metadata for familiar screening metrics; does not claim metrics are computed.
CREATE TABLE IF NOT EXISTS screener_metric_group (
 group_code text PRIMARY KEY,group_name text NOT NULL,sort_order integer NOT NULL
);
CREATE TABLE IF NOT EXISTS screener_metric (
 metric_code text PRIMARY KEY,group_code text NOT NULL REFERENCES screener_metric_group(group_code),
 display_name text NOT NULL,unit text NOT NULL,
 value_type text NOT NULL CHECK(value_type IN ('numeric','boolean','date','category')),
 data_origin text NOT NULL CHECK(data_origin IN ('ohlcv','external','manual','derived')),
 implementation_state text NOT NULL DEFAULT 'planned' CHECK(implementation_state IN ('planned','tested','available')),
 is_active boolean NOT NULL DEFAULT true,
 UNIQUE(group_code,display_name)
);
CREATE TABLE IF NOT EXISTS screener_saved_rule (
 rule_code text PRIMARY KEY,rule_name text NOT NULL,description text,
 logic_json jsonb NOT NULL,enabled boolean NOT NULL DEFAULT false,
 created_at timestamptz NOT NULL DEFAULT now()
);
